const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time periods
  const palmSprings = ee.Geometry.Point([-116.5453, 33.8303]);
  const region = palmSprings.buffer(5000); // 5km buffer

  const target_start = '2017-07-15';
  const target_end = '2017-07-22';

  // 2. Function to get LST in Celsius with QA masking
  function processLST(image) {
    const lst = image.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Convert to Celsius
    const qa = image.select('QA_Day');
    const mask = qa.bitwiseAnd(3).lte(1); // Keep only good quality (bits 0-1 <= 1)
    return lst.updateMask(mask);
  }

  // 3. Get 2017 data
  let col2017 = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate(target_start, target_end)
    .filterBounds(palmSprings)
    .map(processLST);

  const size2017 = col2017.size().getInfo();
  console.log(`2017 Images: ${size2017}`);

  if (size2017 === 0) {
    console.log("No data for 2017 period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 4. Get historical average (2001-2010, same days)
  const years = ee.List.sequence(2001, 2010);

  const historicalImages = years.map(function(year) {
    const y = ee.Number(year).format('%d');
    const start = ee.String(y).cat('-07-15');
    const end = ee.String(y).cat('-07-22');

    return ee.ImageCollection('MODIS/006/MOD11A1')
      .filterDate(start, end)
      .filterBounds(palmSprings)
      .map(processLST)
      .mean();
  });

  const historicalCol = ee.ImageCollection(historicalImages);
  const sizeHistorical = historicalCol.size().getInfo();
  console.log(`Historical years with data: ${sizeHistorical}`);

  if (sizeHistorical === 0) {
    console.log("No historical data found.");
    console.log("<answer>C1</answer>");
    return;
  }

  // 5. Calculate means
  const mean2017 = col2017.mean();
  const meanHistorical = historicalCol.mean();

  // 6. Extract values with pixel count check
  const stats2017 = mean2017.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const statsHistorical = meanHistorical.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const lst2017 = stats2017.LST_Day_1km_mean;
  const count2017 = stats2017.LST_Day_1km_count;
  const lstHistorical = statsHistorical.LST_Day_1km_mean;
  const countHistorical = statsHistorical.LST_Day_1km_count;

  console.log(`2017 LST: ${lst2017 !== null ? lst2017.toFixed(2) : 'null'}°C, Pixels: ${count2017 || 0}`);
  console.log(`Historical LST: ${lstHistorical !== null ? lstHistorical.toFixed(2) : 'null'}°C, Pixels: ${countHistorical || 0}`);

  // 7. Validation and final answer
  if (count2017 === 0 || countHistorical === 0) {
    console.log("No valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  if (lst2017 === null || lstHistorical === null || 
      lst2017 < -50 || lst2017 > 70 || 
      lstHistorical < -50 || lstHistorical > 70) {
    console.log("Invalid LST values.");
    console.log("<answer>C3</answer>");
    return;
  }

  console.log(`Difference: ${(lst2017 - lstHistorical).toFixed(2)}°C`);

  if (lst2017 > lstHistorical) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
